fn bit_wise_xor(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    // Assuming arr1.len() == arr2.len()
    arr1.iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| a ^ b)
        .collect()
}

fn main() {
    let a = vec![1, 2, 3, 4];
    let b = vec![4, 3, 2, 1];
    let c = bit_wise_xor(&a, &b);
    assert_eq!(c, vec![1 ^ 4, 2 ^ 3, 3 ^ 2, 4 ^ 1]);
    println!("Result: {:?}", c);
}